contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        // First call: forward to c itself with a selector C does not have.
        // C has no fallback, so the inner call fails and forward() reverts.
        bool firstReverted;
        uint cBalBefore = address(c).balance;
        try c.forward(address(c), abi.encodeWithSignature("noSuchFunction()")) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        // Second call: after the failed forward, c must still be able to
        // forward successfully to a cooperative callee (this contract, which
        // has a payable receive).
        bool secondReverted;
        try c.forward(address(this), "") {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assert(firstReverted && !secondReverted && address(c).balance == cBalBefore);
    }
    receive() external payable {}
}

