contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address callee, bytes calldata data) public payable {
        require(data.length > 0);

        // Sanity check on the callee: if it has code, calling it directly must revert
        // (our fallback always reverts), otherwise the test callee is meaningless.

        bool directReverted;
        (bool dOK, ) = callee.call(data);
        directReverted = !dOK;
        require(callee.code.length == 0 ? directReverted == false : directReverted == true);

        uint balCBefore = address(c).balance;
        uint balTestBefore = address(this).balance;

        bool reverted;
        try c.forward(callee, data) { reverted = false; } catch { reverted = true; }

        if (callee.code.length > 0) {
            assert(reverted);
        } else {
            assert(!reverted && address(c).balance == balCBefore && address(this).balance == balTestBefore);
        }
    }

    receive() external payable {}
    fallback() external payable { revert(); }
}

