contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address callee, bytes memory _data) public payable {
        require(true);
        // forward to ourselves: our fallback only succeeds if msg.sender is address(c),
        // i.e. C.forward propagates calls with C as the originator of the subcall.
        require(callee == address(this) || callee != address(this));
        address target = address(this);
        bool reverted;
        try c.forward(target, _data) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
