    constructor(C _c) { c = _c; }

    function run(address callee, bytes calldata data) public {
        bool reverted1;
        try c.forward(callee, data) { reverted1 = false; } catch { reverted1 = true; }

        bool reverted2;
        try c.forward(callee, data) { reverted2 = false; } catch { reverted2 = true; }

        // forward's outcome depends only on (callee, data); calling again with the
        // same arguments must produce the same outcome (deterministic reversion).
        assert(reverted1 == reverted2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address callee, bytes calldata data, uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        c.forward(callee, data);
        try c.forward{value: amount}(callee, data) { reverted = false; } catch { reverted = true; }
        // forward is declared nonpayable, so forwarding with any nonzero msg.value
        // must revert for every callee and calldata; with zero value it must not
        // revert due to the value check (outcome depends on callee as usual).
        assert(amount == 0 || reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address callee, bytes calldata data, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // baseline: same call with zero value
        bool revertedZero;
        try c.forward(callee, data) { revertedZero = false; } catch { revertedZero = true; }

        // forward is declared nonpayable, so attaching nonzero value must revert;
        // use a low-level call so the value can be attached to a non-payable target.
        (bool ok,) = address(c).call{value: amount}(
            abi.encodeWithSignature("forward(address,bytes)", callee, data)
        );

        assert(!ok && revertedZero == false || !ok);
    }

    receive() external payable {}
}

contract InvMutTest {
