    constructor(C _c) { c = _c; }

    function run(address callee, bytes calldata data, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // baseline: zero-value call succeeds (callee is an empty address or this contract's receive)
        bool revertedZero;
        try c.forward(callee, data) { revertedZero = false; } catch { revertedZero = true; }

        // nonpayable: attaching value must revert
        bool revertedValue;
        try c.forward{value: amount}(callee, data) { revertedValue = false; } catch { revertedValue = true; }

        assert(revertedValue && !revertedZero);
    }

    receive() external payable {}
}

